    try {
      if (wait) engineLog(`💬 ${added} comment(s) wait for the post to be approved in ${_targetLogLabel(o.groupUrl)} — first look at ${new Date(tasks[0].dueAt).toLocaleTimeString()}`, 'info');
      else engineLog(`💬 ${added} comment(s) queued for ${_targetLogLabel(o.groupUrl)} — first at ${new Date(tasks[0].dueAt).toLocaleTimeString()}`, 'info');
    } catch (_) {}
