  const timer = setTimeout(() => ac.abort(), Number(o.timeoutMs) || 20000);
  try {
    const r = await fetch(url, { credentials: 'include', headers: FB_HTML_HEADERS, signal: ac.signal });
    if (!r || !r.ok || !r.body) return { status: r ? r.status : 0, value: null };
    const rd = r.body.getReader(); const dec = new TextDecoder();
    let buf = ''; let bytes = 0; let value = null;
    try {
      for (;;) {
        const x = await rd.read();
        if (x.done) break;
        bytes += x.value.length;
        buf += dec.decode(x.value, { stream: true });
        value = found(buf);
        if (value || bytes > (Number(o.maxBytes) || 6e6)) break;
      }
    } finally { try { await rd.cancel(); } catch (_) {} }
    return { status: r.status, url: r.url, value, bytes };
  } finally { clearTimeout(timer); }
