    const live = Array.isArray(state.postsCompleted) ? state.postsCompleted : null;
    const li = live ? lateLinkRowIndex(live, item) : -1;
    if (li >= 0) live[li].postUrl = url;
    const d = await chrome.storage.local.get(['postsCompleted', 'mgpPostHistory']);
    const pc = Array.isArray(d && d.postsCompleted) ? d.postsCompleted : null;
    const pi = pc ? lateLinkRowIndex(pc, item) : -1;
    const patch = {};
    if (pi >= 0) { pc[pi] = { ...pc[pi], postUrl: url }; patch.postsCompleted = pc; }
    const hist = Array.isArray(d && d.mgpPostHistory) ? d.mgpPostHistory : null;
    if (hist) {
      for (const rec of hist) {
        const gi = rec && Array.isArray(rec.groups) ? lateLinkRowIndex(rec.groups, item) : -1;
        if (gi >= 0) { rec.groups[gi] = { ...rec.groups[gi], postUrl: url }; patch.mgpPostHistory = hist; break; }
      }
    }
