      try { void ampSend('safe_late_link', { found: true, tries: (Number(it.tries) || 0) + 1, comments: (it.cmt && it.cmt.comments && it.cmt.comments.length) || 0 }); } catch (_) {}
      if (it.cmt && Array.isArray(it.cmt.comments) && it.cmt.comments.length && found.postId) {
        try { await enqueueDelayedComments({ comments: it.cmt.comments, postId: String(found.postId), actorId: it.cmt.actorId, groupUrl: it.link, runStartedAt: it.cmt.runStartedAt, scheduleId: it.cmt.scheduleId, postedAt: Number(it.sentAt) || now }); } catch (_) {}
      }
