    if (hint === 'BUY_AND_SELL') { await noteGroupType(link, hint, 'safe'); return await notAdmin(); }
    const known = groupTypeOf(await readGroupTypes(), key, Date.now());
    if (known) return known === 'BUY_AND_SELL' && await notAdmin();
    const lg = await readListingGroups();
    if (lg && Array.isArray(lg.ids) && /^\d+$/.test(key) && !lg.ids.includes(key)) return false;
    if ((Number(st._bsProbes) || 0) >= BUY_SELL_PROBES_PER_RUN) return false;
    st._bsProbes = (Number(st._bsProbes) || 0) + 1;
