// SW-boot cron tick. Every time the SW wakes — from hibernate, from idle-
// shutdown, from browser start — top-level code re-runs. Firing one cron
// iteration here means a scheduled post whose time fell during the sleep
// window gets picked up within a few seconds of wake (inside the 2-hour
// `isWithinNextHour` grace window), without waiting up to a full minute
// for the next `__sched_wakeup` alarm.
runScheduleCronIteration();

// ── Self-healing reconciliation (observe-and-report ONLY) ────────────────────
// On every SW boot, after the recovery cron tick above has had its chance to
// re-fire anything still inside the 2h grace window, scan for scheduled posts
// that are genuinely orphaned: their fire-time today is in the past, they were
// NOT run today (lastRunKey mismatch), AND they're now outside the fire window
// so the boot cron will NOT recover them. These are the "SW was dead across
// the wakeup for too long" cases that previously vanished silently.
//
// CRITICAL: this NEVER re-fires anything. lastRunKey already guarantees no
// same-day loss-or-dupe, so auto-re-firing here would only add double-post
// risk for ~zero benefit. We purely write a diagnostic report to
// chrome.storage.local._reconciliationReport (same pattern as _lastCronError)
// so the UI / dev can surface "N scheduled posts were missed while your
// browser was closed". Pure storage read → no new permission, no CWS delta.
/**
 * v2026-09-14: once a day, count the stored scheduled posts that can still post and that the Queue
 * has no row for — invisible, and so impossible to delete: the "I deleted it and it still posts"
 * class, measured in the field. Reads the popup's saved Queue (chrome.storage.local); counts only.
 * Also confirms a recorded delete whose stored copy no longer exists, so its entry can age out of
 * the deleted-posts list (a copy removed by the stale sweep was never confirmed).
 */
async function reportQueueOrphans(snapshots) {
  try {
    const list = Array.isArray(snapshots) ? snapshots.filter((x) => x && x.id) : [];
    const deleted = await readDeletedSchedules();
    if (deleted.ok) {
      const stored = new Set(list.map((x) => x.id));
      for (const [id, e] of Object.entries(deleted.map)) {
        if (e && e.gone !== true && !stored.has(id)) await finishDeletingSnapshot(id);
      }
    }
    const { _queueOrphanReportedAt = 0 } = await lsGet('_queueOrphanReportedAt');
    if (Date.now() - (Number(_queueOrphanReportedAt) || 0) < 24 * 60 * 60 * 1000) return;
    const got = await lsGetEx('fb-post-scheduler');
    const saved = got.ok ? got.data['fb-post-scheduler'] : null;
    const rows = (saved && saved.state && Array.isArray(saved.state.scheduledPosts)) ? saved.state.scheduledPosts : null;
    // No saved Queue here (never opened since the storage move) or an unreadable deleted list:
    // nothing honest to count.
    if (!rows || !deleted.ok) return;
    const rowIds = new Set(rows.map((r) => r && r.id).filter(Boolean));
    const now = Date.now();
    const live = list.filter((x) => {
      if (isScheduleDeleted(deleted, x.id)) return false;
      const row = projectSnapshotForQueue(x, { now });
      return !!row && (row.state === 'scheduled' || row.state === 'autoPaused' || row.state === 'missed');
    });
    const orphans = live.filter((x) => !rowIds.has(x.id)).length;
    await lsSet({ _queueOrphanReportedAt: now });
    if (orphans > 0) {
      sentryCaptureMessage('queue-orphan-detected', 'warning', { count: orphans, total: live.length },
        { failure: 'queue-orphan' }, ['queue-orphan-detected']);
    }
  } catch (_) { /* telemetry never affects scheduling */ }
}

function reconcileScheduledPosts() {
  setTimeout(async () => {
    try {
      const db = await openDB("permanentStore", 2, (db) => {
        if (!db.objectStoreNames.contains("snapshots")) {
          db.createObjectStore("snapshots", { keyPath: "id" });
        }
      });
      const tx = db.transaction("snapshots", "readonly");
      const store = tx.objectStore("snapshots");
      const snapshots = await new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => resolve([]);
      });

      const now = new Date();
      const todayKey = todayRunKey();
      const cutoffMs = 60 * 120 * 1000 + 60 * 1000; // mirror isWithinFireWindow: 2h + 1min
      const missed = [];

      for (const snapshot of snapshots) {
        try {
          if (!snapshot || snapshot.status === 'success') continue;
          const schedule = snapshot.metadata?.schedule;
          if (!schedule || !schedule.time) continue;
          // Only flag a snapshot the boot cron did NOT already run today.
          if (snapshot.lastRunKey === todayKey) continue;

          const [hours, minutes] = String(schedule.time).split(":").map(Number);
          if (Number.isNaN(hours) || Number.isNaN(minutes)) continue;
          const todayAtTime = new Date(
            now.getFullYear(), now.getMonth(), now.getDate(), hours, minutes, 0, 0
          );
          const diff = now.getTime() - todayAtTime.getTime();
          // Past its time today AND beyond what the boot cron can recover.
          if (diff > cutoffMs) {
            missed.push({
              id: snapshot.id,
              frequency: schedule.frequency || 'unknown',
              scheduledTime: schedule.time,
              lateMinutes: Math.round(diff / 60000),
              groupCount: Array.isArray(snapshot.items) ? snapshot.items.length : 0,
            });
          }
        } catch (_) { /* per-snapshot guard — never abort the whole scan */ }
      }

      const report = { ts: Date.now(), scanned: snapshots.length, missedCount: missed.length, missed };
      chrome.storage.local.set({ _reconciliationReport: report });
      await reportQueueOrphans(snapshots);
      if (missed.length) {
        console.warn('[reconcile] ' + missed.length +
          ' scheduled post(s) missed while the browser/SW was down — see _reconciliationReport',
          missed);
      } else {
        console.log('[reconcile] no orphaned scheduled posts (scanned ' + snapshots.length + ')');
      }
    } catch (err) {
      // Fully non-fatal — reconciliation is diagnostic only.
      try {
        chrome.storage.local.set({
          _reconciliationReport: { ts: Date.now(), error: String(err?.message || err) },
        });
      } catch (_) {}
    }
  }, 0);
}
