chrome.runtime.onConnect.addListener((port) => {
  if (port.name === "snapshotPort") {
    port.onMessage.addListener((msg) => {
      if (msg.action === "fetchSnapshotItems") {
        fetchSnapshotItemsInChunks(msg.snapshotId, port);
      }
    });
  }

  if (port.name === "posting-keep-alive") {
    // content.js opens this port for the lifetime of the posting operation.
    // A long-lived port is the most reliable way to keep the MV3 Service Worker
    // alive — Chrome will not terminate the SW as long as at least one port is open.
    // We only need to hold the reference; no messages need to be exchanged.
    port.onDisconnect.addListener(() => {
      // Port closed: content script unloaded (tab navigated/closed).
      // Nothing to do — the finally block in initiatePostToFBAction handles cleanup.
    });
  }

  if (port.name === "worker-lifeline") {
    // C5: ping the offscreen worker every 20s so the port carries traffic.
    // An idle port can still be reclaimed by Chrome; an actively-messaged one
    // keeps the SW considered "busy". Pong responses are received but we
    // don't need to act on them — the traffic itself is the signal.
    const pingInterval = setInterval(() => {
      try { port.postMessage({ type: 'ping' }); } catch (_) {}
    }, 20000);
    port.onDisconnect.addListener(() => clearInterval(pingInterval));
  }
});

async function fetchSnapshotItemsInChunks(snapshotId, port) {
  const CHUNK_SIZE = 1024 * 1024;
  // v2026-10-19 · JAVASCRIPT-49: the popup that asked for these files can close mid-transfer; a post to its port then
  // throws inside this async callback (an unhandled rejection) and the database stayed open. Stop quietly instead.
  let _gone = false;
  try { port.onDisconnect.addListener(() => { _gone = true; }); } catch (_) { _gone = true; }
  const _send = (m) => { if (_gone) return false; try { port.postMessage(m); return true; } catch (_) { _gone = true; return false; } };
  const _drop = () => { if (_gone) return; try { port.disconnect(); } catch (_) {} _gone = true; };

  const dbReq = indexedDB.open("permanentStore", 2);
  dbReq.onsuccess = () => {
    const database = dbReq.result;
    const tx = database.transaction("snapshots", "readonly");
    const store = tx.objectStore("snapshots");

    const request = store.get(snapshotId);

    request.onsuccess = async () => {
      try {
        const snapshot = request.result;

        if (!snapshot) {
          _drop();
          return;
        }

        const items = snapshot.items || [];

        for (let i = 0; i < items.length && !_gone; i++) {
          const { key, value } = items[i];
          const blob = value.blob;
          const arrayBuffer = await blob.arrayBuffer();
          const totalChunks = Math.ceil(arrayBuffer.byteLength / CHUNK_SIZE);

          for (let j = 0; j < totalChunks; j++) {
            const start = j * CHUNK_SIZE;
            const end = Math.min(start + CHUNK_SIZE, arrayBuffer.byteLength);
            const chunk = arrayBuffer.slice(start, end);

            if (!_send({
              action: "receiveChunk",
              index: j,
              total: totalChunks,
              key,
              type: value.type,
              itemIndex: i,
              chunk: Array.from(new Uint8Array(chunk)),
            })) break;
          }
        }

        _send({
          action: "allChunksSent",
          itemsCount: items.length,
        });
      } catch (_) {
        _drop();   // a file that cannot be read ends the transfer the same way a missing post does
      } finally {
        try { database.close(); } catch (_) {}
      }
    };

    request.onerror = () => {
      try { database.close(); } catch (_) {}
      _drop();
    };
  };

  dbReq.onerror = () => {
    _drop();
  };
}

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.action == "schedulePostDone") {
    if (typeof msg.snapShotId !== "string") {
      sendResponse({ ok: false, error: "invalid_id" });
      return;
    }
    // markSnapshotAsDone uses IndexedDB callbacks (not promises). Wrap in a
    // Promise so we can await the tx.oncomplete before closing the message
    // channel — otherwise an SW hibernation between delete-request success and
    // transaction-complete could lose the delete and re-fire the snapshot on
    // the next cron iteration. The `return true` keeps the channel open for
    // the async sendResponse below.
    new Promise((resolve) => {
      const request = indexedDB.open("permanentStore", 2);
      request.onsuccess = () => {
        const db = request.result;
        const tx = db.transaction("snapshots", "readwrite");
        const store = tx.objectStore("snapshots");
        store.delete(msg.snapShotId);
        tx.oncomplete = () => {
          unmarkTriggered(msg.snapShotId);
          console.log(`🗑️ Snapshot '${msg.snapShotId}' deleted (once-post complete).`);
          resolve(true);
        };
        tx.onerror = () => {
          console.error(`❌ Failed to delete snapshot '${msg.snapShotId}':`, tx.error);
          resolve(false);
        };
      };
      request.onerror = () => {
        console.error(`❌ Failed to open DB for snapshot deletion:`, request.error);
        resolve(false);
      };
    }).then((ok) => {
      try { sendResponse({ ok }); } catch (_) { /* channel may have closed */ }
    });
    return true; // keep message channel open for async sendResponse
  }
});

